/// VM replay implementations for process bindings.
#[inline]
fn destack_process_args_list_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        PROCESS_ARGS_LIST,
        binding.replay_payload_for(PROCESS_ARGS_LIST)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_process_args(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_process_args(binding, context)
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<vm::StringHandle> = value.clone();
                let result_recorded_raw = result_value.values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item = decode_string(
                        context,
                        result_recorded_item_value,
                        "result_recorded_item",
                        "item",
                    )?;
                    let result_recorded_item_recorded = {
                        let result_recorded_item_recorded_ref = context
                            .string_ref(result_recorded_item)
                            .map_err(|error| RuntimeError::from(error).boxed())?;
                        result_recorded_item_recorded_ref.as_str().to_string()
                    };
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = ProcessArgsListReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    ProcessArgsListReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder =
                        VmSlice::<vm::StringHandle>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value = context
                            .string_handle(vm_result_item.as_str())
                            .map_err(Box::<RuntimeError>::from)?;
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_process_args_list_result(context, result)?;
    Ok(result)
}

#[inline]
fn destack_process_cwd_chdir_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
    path: fs::OsPathVm,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        PROCESS_CWD_CHDIR,
        binding.replay_payload_for(PROCESS_CWD_CHDIR)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_process_chdir(binding, context, path),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_process_chdir(binding, context, path)
            }
        },
        |_context, result| {
            if let Ok(()) = result {
                let result_recorded = ();
                let payload = ProcessCwdChdirReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    ProcessCwdChdirReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |_context, payload| {
            // replay result
            match payload.result {
                Ok(()) => Ok(()),
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_process_cwd_chdir_result(context, result)?;
    Ok(result)
}

