#[inline]
fn destack_process_ids_groups_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        PROCESS_IDS_GROUPS,
        binding.replay_payload_for(PROCESS_IDS_GROUPS)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_process_groups(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_process_groups(binding, context)
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmSlice<GroupId> = value.clone();
                let result_recorded_raw = result_value.values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item_inner = decode_uint32(
                        result_recorded_item_value,
                        "result_recorded_item_inner",
                        "item",
                    )?;
                    let result_recorded_item = GroupId(result_recorded_item_inner);
                    let result_recorded_item_recorded = result_recorded_item;
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = ProcessIdsGroupsReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    ProcessIdsGroupsReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder = VmSlice::<GroupId>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value = vm_result_item;
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_process_ids_groups_result(context, result)?;
    Ok(result)
}

